namespace {
void require(bool value,const char*message){if(!value)throw std::runtime_error(message);}
template<class E,class F>void rejects(F fn){bool caught=false;try{fn();}catch(const E&){caught=true;}require(caught,"expected exception");}
using State=std::vector<int>;
std::map<State,bool>normal_memo,misere_memo;
bool game_tree(State state,bool misere){std::sort(state.begin(),state.end());state.erase(std::remove(state.begin(),state.end(),0),state.end());auto&memo=misere?misere_memo:normal_memo;const auto found=memo.find(state);if(found!=memo.end())return found->second;if(state.empty())return misere;for(std::size_t i=0;i<state.size();++i)for(int remaining=0;remaining<state[i];++remaining){auto next=state;next[i]=remaining;if(!game_tree(next,misere))return memo[state]=true;}return memo[state]=false;}
void nim_games(){std::size_t cases=0;for(int n=0;n<=6;++n){std::size_t states=1;for(int i=0;i<n;++i)states*=5;for(std::size_t code=0;code<states;++code){State a(n);auto value=code;for(auto&x:a){x=value%5;value/=5;}const auto original=a;for(bool misere:{false,true}){const bool want=game_tree(a,misere),actual=misere?cp::misere_nim_winning(a):cp::nim_winning(a);require(want==actual,"Nim outcome vs complete game tree");const auto move=misere?cp::misere_nim_winning_move(a):cp::nim_winning_move(a);const bool has_stones=std::any_of(a.begin(),a.end(),[](int x){return x>0;});require(bool(move)==(want&&has_stones),"winning move presence, including empty misere position");if(move){require(move->pile<a.size()&&move->remaining<std::uint64_t(a[move->pile])&&move->removed==std::uint64_t(a[move->pile])-move->remaining,"legal removal and original pile index");auto next=a;next[move->pile]=int(move->remaining);require(!game_tree(next,misere),"move hands opponent a losing state");if(!misere)require(cp::nim_sum(next)==0,"normal move leaves xor zero");}}require(a==original,"Nim input immutable");++cases;}}
 std::cout<<cases<<" heap vectors through 6 piles: complete normal/misere game trees and legal winning moves passed\n";}
void mex_values(){std::size_t cases=0;for(int n=0;n<=7;++n){int count=1;for(int i=0;i<n;++i)count*=4;for(int code=0;code<count;++code){int x=code;std::vector<int>a(n);for(auto&v:a){v=x%4;x/=4;}std::set<int>seen(a.begin(),a.end());int want=0;while(seen.count(want))++want;require(cp::grundy_mex(a)==want,"mex vs ordered set membership");++cases;}}require(cp::grundy_mex({0,1,std::numeric_limits<int>::max(),1})==2,"large Grundy label does not size allocation");std::cout<<cases<<" Grundy mex lists through length 7 passed\n";}
std::vector<int> naive_grundy(const std::vector<std::vector<int>>&moves){std::vector<int>g(moves.size(),-1);std::function<int(int)>solve=[&](int v){if(g[v]>=0)return g[v];std::set<int>options;for(int to:moves[v])options.insert(solve(to));int value=0;while(options.count(value))++value;return g[v]=value;};for(int i=0;i<int(moves.size());++i)solve(i);return g;}
bool product_tree(const std::vector<std::vector<int>>&moves,std::vector<int>state,std::map<std::vector<int>,bool>&memo){std::sort(state.begin(),state.end());const auto found=memo.find(state);if(found!=memo.end())return found->second;for(std::size_t i=0;i<state.size();++i)for(int to:moves[state[i]]){auto next=state;next[i]=to;if(!product_tree(moves,next,memo))return memo[state]=true;}return memo[state]=false;}
void check_dag(const std::vector<std::vector<int>>&moves,bool products){const auto original=moves;cp::DAGGame game(moves);auto result=cp::calculate_grundy(moves);require(game.grundy()==naive_grundy(moves)&&result.values==game.grundy(),"Grundy values vs recursive set mex");const int n=game.size();require(result.topological_order.size()==moves.size(),"topological order size");std::vector<int>rank(n,-1);for(int i=0;i<n;++i){const int v=result.topological_order[i];require(v>=0&&v<n&&rank[v]<0,"topological order is a permutation");rank[v]=i;}for(int v=0;v<n;++v){for(int to:moves[v])require(rank[v]<rank[to],"every move goes forward");require(game.winning(v)==(game.grundy(v)!=0),"single state outcome");auto move=game.winning_move(v);require(bool(move)==game.winning(v),"single winning move existence");if(move)require(std::find(moves[v].begin(),moves[v].end(),*move)!=moves[v].end()&&!game.winning(*move),"single legal move to zero");for(int value=0;value<=n;++value){const auto to=game.move_to_grundy(v,value);auto it=std::find_if(moves[v].begin(),moves[v].end(),[&](int u){return game.grundy(u)==value;});require(bool(to)==(it!=moves[v].end())&&(!to||*to==*it),"first move for arbitrary target Grundy");}}
 require(moves==original&&game.transitions()==moves,"input unchanged and transitions retained");require(!game.winning(std::vector<int>{})&&!game.winning_move(std::vector<int>{}),"empty sum loses");if(products){std::map<State,bool>memo;for(int count=0;count<=3;++count){int size=1;for(int i=0;i<count;++i)size*=n;for(int code=0;code<size;++code){auto x=code;State positions(count);for(auto&v:positions){v=x%n;x/=n;}const bool want=product_tree(moves,positions,memo);require(game.winning(positions)==want,"DAG sum vs complete product game");auto move=game.winning_move(positions);require(bool(move)==want,"DAG sum winning move existence");if(move){require(move->component<positions.size()&&move->from==positions[move->component]&&std::find(moves[move->from].begin(),moves[move->from].end(),move->to)!=moves[move->from].end(),"DAG sum changes one token along an edge");positions[move->component]=move->to;require(!product_tree(moves,positions,memo)&&game.nim_sum(positions)==0,"DAG sum move leaves losing product");}}}}
}
void dags(std::mt19937_64&rng){std::size_t count=0;for(int n=0;n<=5;++n){std::vector<std::pair<int,int>>edges;for(int i=0;i<n;++i)for(int j=i+1;j<n;++j)edges.emplace_back(i,j);for(unsigned mask=0;mask<(1U<<edges.size());++mask){std::vector<std::vector<int>>moves(n);for(std::size_t i=0;i<edges.size();++i)if(mask>>i&1)moves[edges[i].first].push_back(edges[i].second);check_dag(moves,true);++count;}}
 for(int trial=0;trial<350;++trial){const int n=rng()%12;std::vector<int>order(n);std::iota(order.begin(),order.end(),0);std::shuffle(order.begin(),order.end(),rng);std::vector<std::vector<int>>moves(n);for(int i=0;i<n;++i)for(int j=i+1;j<n;++j)if(rng()%4==0){moves[order[i]].push_back(order[j]);if(rng()%3==0)moves[order[i]].push_back(order[j]);}check_dag(moves,true);cp::Graph<long long>graph(n,cp::GraphKind::Directed);for(int v=0;v<n;++v)for(int to:moves[v])graph.add_edge(v,to,std::numeric_limits<long long>::min());require(cp::calculate_grundy(graph).values==cp::calculate_grundy(moves).values&&cp::DAGGame(graph).grundy()==cp::DAGGame(moves).grundy(),"directed Graph adapter ignores edge costs");}
 std::cout<<count<<" ordered DAGs + 350 relabelled multigraph DAGs: all Grundy values, target moves and product games through 3 tokens passed\n";}
void invalid_and_limits(){for(const auto&a:std::vector<std::vector<int>>{{-1},{1,-1,2},{0,-1}}){rejects<std::invalid_argument>([&]{cp::nim_sum(a);});rejects<std::invalid_argument>([&]{cp::nim_winning(a);});rejects<std::invalid_argument>([&]{cp::nim_winning_move(a);});rejects<std::invalid_argument>([&]{cp::misere_nim_winning(a);});rejects<std::invalid_argument>([&]{cp::misere_nim_winning_move(a);});}rejects<std::invalid_argument>([]{cp::grundy_mex({-1});});for(const auto&bad:std::vector<std::vector<std::vector<int>>>{{{0}},{{1},{0}},{{},{2},{1}}}){rejects<std::invalid_argument>([&]{cp::calculate_grundy(bad);});rejects<std::invalid_argument>([&]{cp::DAGGame game(bad);});}for(const auto&bad:std::vector<std::vector<std::vector<int>>>{{{-1}},{{1}},{{},{2}}})rejects<std::out_of_range>([&]{cp::calculate_grundy(bad);});rejects<std::invalid_argument>([]{cp::calculate_grundy(cp::Graph<int>(2));});rejects<std::invalid_argument>([]{cp::DAGGame game(cp::Graph<int>(0));});cp::DAGGame game(std::vector<std::vector<int>>{{},{0}});rejects<std::out_of_range>([&]{game.grundy(-1);});rejects<std::out_of_range>([&]{game.winning(2);});rejects<std::out_of_range>([&]{game.winning_move(2);});rejects<std::out_of_range>([&]{game.nim_sum({1,2});});rejects<std::out_of_range>([&]{game.winning_move(std::vector<int>{0,-1});});rejects<std::invalid_argument>([&]{game.move_to_grundy(1,-1);});
 const auto hi=std::numeric_limits<std::uint64_t>::max();for(const auto&a:std::vector<std::vector<std::uint64_t>>{{hi},{hi,hi},{hi,1},{hi,hi-1,1},{std::uint64_t(1)<<63,hi}}){std::uint64_t sum=0;for(auto x:a)sum^=x;require(cp::nim_sum(a)==sum,"unsigned 64-bit XOR including high bit");auto normal=cp::nim_winning_move(a);require(bool(normal)==bool(sum),"full width normal move");if(normal){auto b=a;b[normal->pile]=normal->remaining;require(cp::nim_sum(b)==0&&normal->remaining<a[normal->pile],"full width normal zero xor");}auto misere=cp::misere_nim_winning_move(a);require(bool(misere)==cp::misere_nim_winning(a),"full width misere move");if(misere){auto b=a;b[misere->pile]=misere->remaining;require(!cp::misere_nim_winning(b),"full width misere losing successor");}}
 require(cp::nim_sum(std::vector<signed char>{1,2,3})==0&&cp::nim_sum(std::vector<unsigned char>{255,1})==254,"narrow integer pile types");require(cp::nim_sum(std::vector<long long>{std::numeric_limits<long long>::max(),1})==std::uint64_t(std::numeric_limits<long long>::max()-1),"signed maximum pile");cp::DAGGame copy=game;auto values=game.grundy();values[0]=999;require(copy.grundy(0)==0&&game.grundy(0)==0,"results own their data and const access");std::cout<<"empty/misere terminals, closed loops/unreachable cycles, invalid endpoints/queries and full 64-bit piles passed\n";}
void large(){const int n=200000;std::vector<std::uint64_t>piles(n,std::numeric_limits<std::uint64_t>::max());require(!cp::nim_winning(piles)&&!cp::misere_nim_winning(piles),"large piles without summing overflowing totals");piles.back()=1;require(cp::nim_winning(piles)&&cp::misere_nim_winning(piles),"large winning full-width piles");std::vector<std::vector<int>>moves(n);for(int i=1;i<n;++i)moves[i].push_back(i-1);cp::DAGGame game(std::move(moves));for(int i=0;i<n;++i)require(game.grundy(i)==i%2,"deep path parity without recursion");std::vector<int>tokens(n,n-1);require(!game.winning(tokens),"200000 independent tokens");moves.assign(1500,{});for(int i=0;i<1500;++i)for(int j=0;j<i;++j)moves[i].push_back(j);auto g=cp::calculate_grundy(moves);for(int i=0;i<1500;++i)require(g.values[i]==i,"dense DAG grows Grundy values and mex remains linear in edges");moves.assign(2,{});moves[1].assign(1000000,0);require(cp::calculate_grundy(moves).values==std::vector<int>({0,1}),"one million parallel moves do not change mex");std::vector<int>all(200000);std::iota(all.begin(),all.end(),0);require(cp::grundy_mex(all)==200000,"large mex");std::cout<<"200000 heaps / vertices / tokens / mex labels, 1500-vertex dense DAG and 1000000 parallel moves passed\n";}
}
int main(){std::mt19937_64 rng(324024);nim_games();mex_values();dags(rng);invalid_and_limits();large();}
